draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // sun
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.fill();

  // earth
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 70, 30, 0, 2 * Math.PI);
  ctx.fill();

  // seed
  ctx.fillStyle = 'brown';
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 100, 10, 0, 2 * Math.PI);
  ctx.fill();

  // sprout
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 110);
  ctx.lineTo(W/2, H/2 + 110 - 50 * Math.sin(t));
  ctx.stroke();

  // leaves
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 110 - 50 * Math.sin(t), 10 * Math.sin(t), 0, 2 * Math.PI);
  ctx.fill();

  ctx.restore();
}
